using System.Data; using Microsoft.Data.SqlClient; using Garage.DTO; namespace Garage.DAL; public class GarageRepository {
 public DataTable Query(string sql){using var c=Db.Open();using var da=new SqlDataAdapter(sql,c);var t=new DataTable();da.Fill(t);return t;}
 public DataTable SearchCars(string k){using var c=Db.Open();using var da=new SqlDataAdapter("SELECT x.BienSo,x.HieuXe,x.NamSanXuat,k.MaKH,k.TenKH,k.DienThoai FROM Xe x JOIN KhachHang k ON k.MaKH=x.MaKH WHERE x.BienSo LIKE @k OR k.TenKH LIKE @k",c);da.SelectCommand!.Parameters.AddWithValue("@k","%"+k+"%");var t=new DataTable();da.Fill(t);return t;}
 public DataTable Parts()=>Query("SELECT MaPhuTung,TenPhuTung,DonGia,SoLuongTon FROM PhuTung ORDER BY TenPhuTung"); public DataTable Customers()=>Query("SELECT MaKH,TenKH,DienThoai,DiaChi FROM KhachHang"); public DataTable Repairs()=>Query("SELECT p.MaPhieu,p.BienSo,p.NgayNhan,p.NoiDungSua,p.TongTien,p.TrangThai FROM PhieuSuaChua p ORDER BY p.MaPhieu DESC");
 public void AddCustomerCar(string name,string phone,string address,string plate,string model,int year){using var c=Db.Open();using var tx=c.BeginTransaction();try{int id;using(var cmd=new SqlCommand("INSERT KhachHang(TenKH,DienThoai,DiaChi); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){cmd.Parameters.AddWithValue("@x",0);cmd.CommandText="INSERT KhachHang(TenKH,DienThoai,DiaChi) VALUES(@n,@p,@a); SELECT CAST(SCOPE_IDENTITY() AS int)";cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@p",phone);cmd.Parameters.AddWithValue("@a",address);id=(int)cmd.ExecuteScalar()!;}using var car=new SqlCommand("INSERT Xe(BienSo,MaKH,HieuXe,NamSanXuat) VALUES(@b,@id,@h,@y)",c,tx);car.Parameters.AddWithValue("@b",plate);car.Parameters.AddWithValue("@id",id);car.Parameters.AddWithValue("@h",model);car.Parameters.AddWithValue("@y",year);car.ExecuteNonQuery();tx.Commit();}catch{tx.Rollback();throw;}}
 public void AddPart(string name,decimal price,int stock){using var c=Db.Open();using var cmd=new SqlCommand("INSERT PhuTung(TenPhuTung,DonGia,SoLuongTon) VALUES(@n,@p,@s)",c);cmd.Parameters.AddWithValue("@n",name);cmd.Parameters.AddWithValue("@p",price);cmd.Parameters.AddWithValue("@s",stock);cmd.ExecuteNonQuery();}
 public void CreateRepair(string plate,string note,List<RepairItem> items){if(items.Count==0)throw new Exception("Cần ít nhất một phụ tùng trong phiếu.");using var c=Db.Open();using var tx=c.BeginTransaction();try{int id;using(var cmd=new SqlCommand("INSERT PhieuSuaChua(BienSo,NoiDungSua) VALUES(@b,@n); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){cmd.Parameters.AddWithValue("@b",plate);cmd.Parameters.AddWithValue("@n",note);id=(int)cmd.ExecuteScalar()!;}decimal total=0;foreach(var x in items){decimal price;using(var p=new SqlCommand("SELECT DonGia FROM PhuTung WHERE MaPhuTung=@id",c,tx)){p.Parameters.AddWithValue("@id",x.MaPhuTung);price=Convert.ToDecimal(p.ExecuteScalar()??throw new Exception("Không tìm thấy phụ tùng."));}using(var stock=new SqlCommand("UPDATE PhuTung SET SoLuongTon=SoLuongTon-@q WHERE MaPhuTung=@id AND SoLuongTon>=@q",c,tx)){stock.Parameters.AddWithValue("@q",x.SoLuong);stock.Parameters.AddWithValue("@id",x.MaPhuTung);if(stock.ExecuteNonQuery()!=1)throw new Exception("Phụ tùng không đủ tồn kho. Giao dịch đã được hoàn tác.");}using(var line=new SqlCommand("INSERT ChiTietSuaChua(MaPhieu,MaPhuTung,SoLuong,TienCong,DonGia) VALUES(@p,@id,@q,@labor,@price)",c,tx)){line.Parameters.AddWithValue("@p",id);line.Parameters.AddWithValue("@id",x.MaPhuTung);line.Parameters.AddWithValue("@q",x.SoLuong);line.Parameters.AddWithValue("@labor",x.TienCong);line.Parameters.AddWithValue("@price",price);line.ExecuteNonQuery();}total+=(price*x.SoLuong)+x.TienCong;}using(var up=new SqlCommand("UPDATE PhieuSuaChua SET TongTien=@t,TrangThai=N'Đã hoàn thành' WHERE MaPhieu=@id",c,tx)){up.Parameters.AddWithValue("@t",total);up.Parameters.AddWithValue("@id",id);up.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}
 public void Pay(int id){using var c=Db.Open();using var cmd=new SqlCommand("UPDATE PhieuSuaChua SET TrangThai=N'Đã thanh toán' WHERE MaPhieu=@id AND TrangThai=N'Đã hoàn thành'",c);cmd.Parameters.AddWithValue("@id",id);if(cmd.ExecuteNonQuery()!=1)throw new Exception("Phiếu không tồn tại hoặc chưa hoàn thành.");}
}